seq = "".join(l.strip() for l in open("region.fasta").read().splitlines()[1:]).upper()
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
stops = {"TAA","TAG","TGA"}

def find_orfs(s, min_aa=30):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        for j in range(frame, len(s), 3):
            cod=s[j:j+3]
            if len(cod)<3: break
            if cod=="ATG" and start is None:
                start=j
            elif cod in stops and start is not None:
                aa=(j-start)//3
                if aa>=min_aa:
                    res.append((start,j+3,aa,frame,"+"))
                start=None
    return res

forwards = find_orfs(seq)
rev = find_orfs(rc(seq))
print("Forward ORFs >=30 aa:")
for o in sorted(forwards,key=lambda x:-x[2]):
    print(o)
print("\nReverse-complement ORFs >=30 aa (coords on original):")
L=len(seq)
for s,e,aa,f,st in sorted(rev,key=lambda x:-x[2]):
    os, oe = L-e, L-s
    print((os,oe,aa,f,"-"))

seq = "".join(l.strip() for l in open("region.fasta").read().splitlines()[1:]).upper()
L=len(seq)
stops={"TAA","TAG","TGA"}
best=(0,None)
for frame in range(3):
    run=0; start=frame
    for j in range(frame, L-2, 3):
        if seq[j:j+3] in stops:
            if run>best[0]: best=(run,start,j)
            run=0; start=j+3
        else:
            run+=1
    if run>best[0]: best=(run,start,j)
print("longest stop-free stretch (bp):", best[0], "1-based", best[1]+1, "-", best[2]+3 if best[2] else None)
